// Card is the resolver for the card field.
func (r *queryResolver) Card(ctx context.Context, id uuid.UUID) (model.CardResult, error) {
	if notRegistered := requirePlayer(ctx); notRegistered != nil {
		return notRegistered, nil
	}
	card, err := r.cardQuery.Get(ctx, id)
	if errors.Is(err, query.ErrCardNotFound) {
		return &model.CardNotFoundError{Message: "card not found"}, nil
	}
	if err != nil {
		return nil, err
	}
	info, err := fromCard(card.Type, card.ID, card.Name, card.Cost, card.Rarity, card.Creature)
	if err != nil {
		return nil, err
	}
	// CardInfo（interface）のうち、結果の union に入る 3 つの型はどれも同じ値で返せる
	result, ok := info.(model.CardResult)
	if !ok {
		return nil, fmt.Errorf("graphql: card info %T is not a card result", info)
	}
	return result, nil
}
